// src/mp/client/ServerProtocol.ts
var PROTOCOL_VERSION = 1;

// src/mp/client/playgroundDuplicateSessionHint.ts
var logged = false;
function maybeLogPlaygroundDuplicateSessionHint(code) {
  if (code !== "DUPLICATE_SESSION" || logged) return;
  if (typeof window === "undefined") return;
  const playground = window.__RUNDOT_GAME_PLAYGROUND__;
  if (!playground?.enabled) return;
  logged = true;
  console.warn(
    '[RUN:playground] DUPLICATE_SESSION: two clients joined with the SAME player identity. Every browser instance sharing one playground base identity (one Google account or one pk_ key) needs its own player. Canonical fixes (see "Test multiple players" in the playground docs):\n  \u2022 Same browser: open players as tabs in one window \u2014 distinct players are assigned automatically.\n  \u2022 Separate browsers/profiles/automation contexts: pin each one with a distinct value, e.g. ?rundotPlayer=player2 (any [a-zA-Z0-9_]{1,32} value, unique per instance).'
  );
}

